import{calculator,CalcError,bool,has,nonneg,pos}from './core.js?ver=a26726e2ad';import{energyCharge,netLines}from './bill.js?ver=a26726e2ad';import{fmt}from './format.js?ver=a26726e2ad';const R=(v)=>Math.round(+v.toFixed(6));const rs=(v)=>fmt(v,'rs');
export const net_billing_payback=calculator((i,d)=>{const r=netLines(i,d,R);const t=d.tariff;if(has(i,'disco')){r.disco=String(i.disco).trim();if(!t.discos?.[r.disco])throw new CalcError('disco_invalid','disco');}
if(!has(i,'before_units')){if(has(i,'system_rs'))throw new CalcError('payback_needs_before_units','before_units');r.payback_calc='For the saving and the payback, enter your monthly units before solar and the system price.';return r;}
const before=nonneg(i,'before_units');if(before<r.import_units)throw new CalcError('before_below_import','before_units');let calc;if(r.tou){const T=t.tou,off=before-r.peak_units;r.before_energy_rs=R(r.peak_units*T.peak+off*T.offpeak);calc=`${fmt(r.peak_units)} peak units × ${fmt(T.peak,'rs2')} + ${fmt(off)} off-peak × ${fmt(T.offpeak,'rs2')}`;}else{const cat=bool(i.protected)&&before<=t.protected[t.protected.length-1].upto?'protected':'unprotected';const e=energyCharge(t,before,cat,r.sanctioned_kw);r.before_energy_rs=R(e.energy_rs);calc=cat==='protected'?`${fmt(before)} units at the protected slab rates`:`${fmt(before)} units at the slab rate of ${fmt(e.rate,'rs2')}`;}
r.before_units=before;r.monthly_saving_rs=Math.max(0,r.before_energy_rs-r.net_energy_rs);r.yearly_saving_rs=r.monthly_saving_rs*12;r.payback_calc=`Without solar: ${calc} = ${rs(r.before_energy_rs)}. Saving = ${rs(r.before_energy_rs)} − ${rs(r.net_energy_rs)} = ${rs(r.monthly_saving_rs)} a month, ${rs(r.yearly_saving_rs)} a year (energy charges only; credit carried forward is not counted).`;if(!has(i,'system_rs')){r.payback_calc+=' Enter the system price for the payback.';return r;}
r.system_rs=pos(i,'system_rs');if(!r.monthly_saving_rs)throw new CalcError('payback_no_saving','before_units');r.payback_years=r.system_rs/r.yearly_saving_rs;r.payback_calc+=` Payback = ${rs(r.system_rs)} ÷ ${rs(r.yearly_saving_rs)} = ${fmt(r.payback_years,'1')} years.`;return r;});
